SELECT 100.0 * SUM(CASE WHEN pa.preferred_foot = 'left' THEN 1 ELSE 0 END) / COUNT(*) AS percentage
FROM Player p
JOIN (
  SELECT player_api_id, preferred_foot
  FROM Player_Attributes pa1
  WHERE date = (
    SELECT MAX(date) FROM Player_Attributes pa2 WHERE pa2.player_api_id = pa1.player_api_id
  )
) pa ON pa.player_api_id = p.player_api_id
WHERE substr(p.birthday,1,4) BETWEEN '1987' AND '1992';

SELECT CASE WHEN total=0 THEN 0 ELSE (elder*100.0)/total END AS percentage
FROM (
  SELECT
    (SELECT COUNT(*) FROM posts WHERE Score>5) AS total,
    (SELECT COUNT(*) FROM posts p JOIN users u ON p.OwnerUserId=u.Id WHERE p.Score>5 AND u.Age>65) AS elder
);

SELECT
  100.0 * COALESCE(
    (SELECT COUNT(DISTINCT l.ID) FROM Laboratory l JOIN Patient p ON p.ID = l.ID WHERE p.SEX = 'F' AND l.UA > 6.5),
    0
  )
  /
  NULLIF(
    (SELECT COUNT(DISTINCT l.ID) FROM Laboratory l JOIN Patient p ON p.ID = l.ID WHERE p.SEX = 'F' AND l.UA IS NOT NULL),
    0
  ) AS percentage;

SELECT COUNT(*) FROM client WHERE gender = 'M' AND district_id IN (
  SELECT district_id FROM district WHERE A15 = (
    SELECT MAX(A15) FROM district WHERE A15 IS NOT NULL AND A15 < (SELECT MAX(A15) FROM district WHERE A15 IS NOT NULL)
  )
);

